}

data class Recipe(
    val id: String,
    val name: String,
    val description: String,
    val category: String,
    val mainIngredient: String,
    val minutes: Int,
    val temperature: Int,
    val servings: Int,
    val calories: Int,
    val difficulty: String,
    val preheat: Boolean,
    val turn: Boolean,
    val ingredients: List<String>,
    val pantryKeys: Set<String>,
    val steps: List<CookStep>,
    val palette: Int,
    val healthy: Boolean = false,
    val imageKey: String? = null,
